package org.eclipse.rdf4j.http.protocol.transaction;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.io.ByteArrayOutputStream;
import java.nio.charset.StandardCharsets;
import java.util.List;

import org.eclipse.rdf4j.http.protocol.transaction.operations.SPARQLUpdateOperation;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.Dataset;
import org.eclipse.rdf4j.query.impl.SimpleDataset;
import org.junit.jupiter.api.Test;

class ExplicitEmptyReadDatasetTransactionTest {

	@Test
	void rejectsExplicitEmptyDatasetEvenWithUpdateTargets() {
		SimpleDataset dataset = new SimpleDataset();
		dataset.setExplicitReadDataset(true);
		dataset.setDefaultInsertGraph(SimpleValueFactory.getInstance().createIRI("urn:insert"));
		dataset.addDefaultRemoveGraph(SimpleValueFactory.getInstance().createIRI("urn:remove"));
		assertThatThrownBy(() -> serialize(dataset)).isInstanceOf(IllegalArgumentException.class)
				.hasMessageContaining("empty read dataset");
	}

	@Test
	void keepsUnconfiguredAndNonemptyDatasetSerialization() throws Exception {
		assertThat(serialize(null)).contains("sparql");
		assertThat(serialize(new SimpleDataset())).contains("dataset");
		SimpleDataset dataset = new SimpleDataset();
		dataset.addDefaultGraph(SimpleValueFactory.getInstance().createIRI("urn:default"));
		dataset.addNamedGraph(SimpleValueFactory.getInstance().createIRI("urn:named"));
		String expected = serialize(dataset);
		dataset.setExplicitReadDataset(true);
		assertThat(serialize(dataset)).isEqualTo(expected).contains("urn:default", "urn:named");
	}

	private static String serialize(Dataset dataset) throws Exception {
		ByteArrayOutputStream output = new ByteArrayOutputStream();
		SPARQLUpdateOperation update = new SPARQLUpdateOperation("DELETE { ?s ?p ?o } WHERE { ?s ?p ?o }",
				null, true, dataset);
		new TransactionWriter().serialize(List.of(update), output);
		return output.toString(StandardCharsets.UTF_8);
	}
}
